ATTACH ':memory:' AS aux; CREATE TABLE aux.t1(a, b); INSERT INTO aux.t1 VALUES('a aux', 'b aux'); CREATE VIEW aux.v3 AS SELECT * FROM t1; CREATE TEMP TABLE t1(a, b); INSERT INTO temp.t1 VALUES('a temp', 'b temp'); DROP VIEW v3; INSERT INTO main.data_log SELECT 'main', a, b FROM main.t1 UNION ALL SELECT 'temp', a, b FROM temp.t1 UNION ALL SELECT 'aux', a, b FROM aux.t1;